import { useEffect, useState } from 'react';

import type {
  CollectorsResponse,
  FactsResponse,
  RiskSummary,
  StoriesResponse,
  UsageSummary,
} from '../api/types';
import { Metric } from '../components/Metric';
import { StoryCard } from '../components/StoryCard';
import {
  factTypeLabel,
  formatDateTime,
  localizedSummary,
  qualityLabel,
  reasonCodeLabel,
  severityLabel,
  sourceStatusLabel,
} from './dashboardLabels';
import { UsageGovernanceSummary } from './UsageGovernanceSummary';

interface Props {
  loadCollectors: () => Promise<CollectorsResponse>;
  loadFacts: () => Promise<FactsResponse>;
  loadStories: () => Promise<StoriesResponse>;
  loadUsageSummary: () => Promise<UsageSummary>;
  loadRiskSummary: () => Promise<RiskSummary>;
  onOpenStory: (storyId: string) => void;
}

type LoadState =
  | { status: 'loading' }
  | { status: 'error' }
  | {
      status: 'ready';
      collectors: CollectorsResponse;
      facts: FactsResponse;
      stories: StoriesResponse;
      usage: UsageSummary;
      risks: RiskSummary;
    };

export function DashboardPage({
  loadCollectors,
  loadFacts,
  loadRiskSummary,
  loadStories,
  loadUsageSummary,
  onOpenStory
}: Props) {
  const [state, setState] = useState<LoadState>({ status: 'loading' });

  useEffect(() => {
    let cancelled = false;
    Promise.all([loadCollectors(), loadFacts(), loadStories(), loadUsageSummary(), loadRiskSummary()])
      .then(([collectors, facts, stories, usage, risks]) => {
        if (!cancelled) setState({ status: 'ready', collectors, facts, stories, usage, risks });
      })
      .catch(() => {
        if (!cancelled) setState({ status: 'error' });
      });
    return () => {
      cancelled = true;
    };
  }, [loadCollectors, loadFacts, loadRiskSummary, loadStories, loadUsageSummary]);

  if (state.status === 'loading') {
    return (
      <section className="panel">
        <h2>正在加载观测数据</h2>
        <p>读取采集器、事实、故事队列和治理指标。</p>
      </section>
    );
  }

  if (state.status === 'error') {
    return (
      <section className="panel">
        <h2>观测数据不可用</h2>
        <p>请确认后端服务在 127.0.0.1:8765 运行。</p>
        <button onClick={() => setState({ status: 'loading' })}>重试</button>
      </section>
    );
  }

  const onlineCollectors = state.collectors.collectors.filter((collector) => collector.source_status === 'online');
  const latestFact = state.facts.facts[0];
  const latestCollector = state.collectors.collectors[0];
  const activeStories = state.stories.stories.filter((story) => story.attention_state !== 'handled_hidden');
  const highRiskCount = state.risks.signals.reduce((total, item) => total + item.count, 0);

  return (
    <div className="dashboard workbench" aria-label="观察故事运营台">
      <section className="context-bar">
        <div>
          <strong>观察故事运营台</strong>
          <span>先看待处理故事，再打开证据链处理；事实列表用于解释故事从哪些脱敏观测归纳而来。</span>
        </div>
        <div className="mini-grid">
          <Mini label="当前采集器" value={latestCollector?.display_name ?? '未注册'} />
          <Mini label="最近事实" value={latestFactTitle(latestFact)} />
          <Mini label="最近心跳" value={formatDateTime(latestCollector?.last_heartbeat_at)} />
        </div>
      </section>

      <section className="metrics" aria-label="核心指标">
        <Metric label="采集器" value={`${onlineCollectors.length}/${state.collectors.collectors.length}`} note="在线 / 总数" />
        <Metric label="事实" value={state.facts.facts.length} note="已接收结构化事实" />
        <Metric label="待处理故事" value={activeStories.length} note="active / needs_review" />
        <Metric label="风险信号" value={highRiskCount} note="高风险与敏感触达" />
      </section>

      <div className="workbench-grid">
        <aside className="panel flush workbench-side" aria-label="观测上下文">
          <div className="panel-header">
            <h2>接入与筛选</h2>
            <span className={onlineCollectors.length ? 'badge green' : 'badge amber'}>
              {onlineCollectors.length ? '已收到心跳' : '等待采集器'}
            </span>
          </div>
          <div className="panel-body">
            <div className="context-stack">
              <Mini label="事实质量" value={qualitySummary(state.facts)} />
              <Mini label="待传 outbox" value={String(sumBacklog(state.collectors))} />
              <Mini label="重点队列" value={queueSummary(activeStories.length)} />
            </div>
            {state.collectors.collectors.length === 0 ? (
              <p>还没有采集器注册。请下载 Windows 包并运行 start。</p>
            ) : (
              <div className="row-list">
                {state.collectors.collectors.slice(0, 4).map((collector) => (
                  <div className="info-row" key={collector.collector_id}>
                    <div>
                      <strong>{collector.display_name}</strong>
                      <small>{collector.collector_id}</small>
                    </div>
                    <span>{sourceStatusLabel(collector.source_status)} / {reasonCodeLabel(collector.reason_code)}</span>
                    <span className="badge teal">backlog {collector.outbox_backlog}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </aside>

        <section className="panel flush story-workbench" aria-label="观察故事">
          <div className="panel-header">
            <h2>观察故事队列</h2>
            <span className="badge violet">{activeStories.length} 条待看</span>
          </div>
          <p className="panel-intro">故事是系统从事实、证据投影、用量和风险信号中归纳出的处理对象；这里不直接展示原始日志或提示词。</p>
          <div className="panel-body">
            {state.stories.stories.length === 0 ? (
