function FilterSelect({
  children,
  label,
  onChange,
  value
}: {
  children: ReactNode;
  label: string;
  onChange: (value: string) => void;
  value: string;
}) {
  return (
    <label>
      {label}
      <select value={value} onChange={(event) => onChange(event.target.value)}>
        {children}
      </select>
    </label>
  );
}

function filterByWindow(facts: ObservedFact[], window: string): ObservedFact[] {
  if (window === 'all') return facts;
  const cutoffMs = Date.now() - (window === '24h' ? 24 : 24 * 7) * 60 * 60 * 1000;
  return facts.filter((fact) => Date.parse(fact.occurred_at) >= cutoffMs);
}
