          ))}
        </ul>
      </section>
      <section>
        <h3>最近审计</h3>
        <p>{story.recent_audit_summary.latest}</p>
        <ul>
          {story.recent_audit_summary.events.map((event) => (
            <li key={`${event.action}-${event.created_at}`}>
