      {state.status === 'error' && <p role="alert">配置不可用。请确认后端服务运行后重试。</p>}
      {state.status === 'ready' && (
        <form
          className="drawer-form"
          onSubmit={async (event) => {
            event.preventDefault();
            setSaveState('saving');
            try {
              const policy = await savePolicy({
                expected_version: state.policy.policy_version,
                template_enabled: templateEnabled,
                upload_raw: uploadRaw,
                collection_policy: collectionPolicy,
                diagnostic_policy: diagnosticPolicy
              });
              const audit = await loadAudit();
              setState({ status: 'ready', packageConfig: state.packageConfig, policy, audit });
              setSaveState('saved');
            } catch {
              setSaveState('error');
            }
          }}
        >
          <a href={downloadUrl} download="agent-observer-windows.zip">
            下载 agent-observer-windows.zip
          </a>
          <p>仅下载客户端时不需要点击“保存策略”；只有修改下方策略字段后才会写入服务端 effective_policy。</p>
          <p>
            安装包 {state.packageConfig.filename}，配置 {state.packageConfig.config_path}，sha256{' '}
            {state.packageConfig.sha256.slice(0, 8)}
          </p>
          <p>策略版本 v{state.policy.policy_version}</p>
          <label>
            <input type="checkbox" checked={templateEnabled} onChange={(event) => setTemplateEnabled(event.target.checked)} />
            启用 Codex 来源模板
          </label>
          <label>
            <input type="checkbox" checked={uploadRaw} onChange={(event) => setUploadRaw(event.target.checked)} />
            允许上传脱敏证据投影（不含原文）
          </label>
          <label>
            采集策略
            <textarea value={collectionPolicy} onChange={(event) => setCollectionPolicy(event.target.value)} />
          </label>
          <label>
            诊断策略
            <textarea value={diagnosticPolicy} onChange={(event) => setDiagnosticPolicy(event.target.value)} />
          </label>
          <button className="primary" disabled={saveState === 'saving'} type="submit">
            {saveState === 'saving' ? '正在保存策略' : '保存策略'}
          </button>
          {saveState === 'saved' && <p role="status">策略已保存为 v{state.policy.policy_version}</p>}
          {saveState === 'error' && <p role="alert">策略更新失败。请重新打开配置后再试。</p>}
          <section aria-label="策略审计">
            <h3>最近审计</h3>
            <p>{state.audit.latest}</p>
          </section>
        </form>
      )}
    </aside>
  );
}
